-- Postal-code to jurisdiction reference data for buyer-supplied locations.
--
-- Source: U.S. Census Bureau, 2020 ZCTA-to-county relationship file
--   https://www2.census.gov/geo/docs/maps-data/data/rel2020/zcta520/tab20_zcta520_county20_natl.txt
-- A work of the United States Government, uncopyrighted under 17 U.S.C. 105.
-- Retrieved 2026-09-29. State derived from the first two digits of the county GEOID.
--
-- Two limitations are deliberate and handled in PostalJurisdictionResolver:
--  1. A ZCTA is not a USPS ZIP code. PO-box-only ZIPs have no ZCTA, so they are absent here
--     and must be reported as unrecognized, never as outside the supported jurisdiction.
--  2. 137 ZCTAs cross a state line. Every state a ZCTA touches gets a row; the one holding the
--     largest share of its land area is marked dominant. The resolver refuses to guess a tax
--     jurisdiction for a crossing postal code and asks the Buyer to state their own.
--
-- This table says only where a postal code is. Whether that jurisdiction is supported is
-- decided by jurisdiction_policies, so adding a state is a policy-pack change, not a code change.
create table postal_jurisdictions (
  postal_code varchar(5) not null,
  jurisdiction varchar(64) not null,
  dominant boolean not null,
  dataset_version varchar(64) not null default 'census-zcta-county-2020',
  primary key (postal_code, jurisdiction)
);

